// Mathematically equivalent, numerically different due to rounding
// (a + c) evaluates to 0.0f, result is 1.0f
float res1 = (a + c) + b; // 1.0f

// (c + b) evaluates to -1e20f (1.0 is absorbed)
// result is 0.0f (or 1e20)
float res2 = a + (c + b); // 0.0f
